@import url("https://fonts.googleapis.com/css2?family=Kufam:ital,wght@1,900&display=swap");

body {
	font-size: 16px;
	line-height: 28px;
}

.container-fluid {
	padding: 0px
}

.title {
	background-color: #007FAE;
	color: white;
	width: 100%;
	height: 60px;
	padding: 0px 100px;
}

.title h2 {
	font-family: 'Kufam', sans-serif;
	float: left;
}

.version {
	color: black;
	float: left;
	margin-top: 15px;
	margin-left: 20px;
    padding: 3px 10px;
    background-color: #f5f5f5;
    border: 1px solid #e3e3e3;
    border-radius: 10px;
    -webkit-box-shadow: inset 0 1px 1px rgba(0, 0, 0, .05);
    box-shadow: inset 0 1px 1px rgba(0, 0, 0, .05);
}

.col-sm-4.well {
	clear: both;
	width: 25%;
	margin-left: 100px;
	height: 100dvh;
	border: 0px;
	border-radius: 0px;
}

.nav li a {
	color: #333;
	border-radius: 0px;
}

.nav-pills>li.active>a, .nav-pills>li.active>a:focus, .nav-pills>li.active>a:hover {
	color: #333;
	background-color: #dbd9d9;
}

.nav li.nav-item {
	font-weight: bold;
	font-size: 18px;
	margin-bottom: 20px;
}

.bslib-nav-spacer {
	border-top: 1px solid #e3e3e3;
	margin: 20px 0px
}

.main {
	padding: 0px 40px;
	max-width: 80%;
}

h3 {
	font-size: 32px;
}

.nameRow {
	margin-top: 30px;
}

#submit_libcal, #submit_email, #submit_instreq {
	margin-top: 33px;
}

.shiny-output-error-validation {
	color: red;
}

.load-container {
	top: 0%;
	width: 8%;
	padding-top: 20px;
}

#lcReset, #emReset, #irReset {
	margin-left: 10px;
}

.helpTOC {
	margin-top: 30px;
	padding-inline-start: 0px;
	border-top: 1px solid #f5f5f5;
}

.helpTOC li {
	font-size: 18px;
	list-style-type: none;
	padding: 10px 0px;
	border-bottom: 1px solid #f5f5f5
}

h4 {
	font-size: 22px;
	margin-top: 40px;
}

h5 {
	font-size: 18px;
	margin-top:30px;
	font-weight: bold;
}

.alert {
	width: 100%;
	margin-top: 30px;
	padding: 16px;
	background-color: rgba(255, 186, 0, 0.05);
}

.alert-title {
  margin-top: 0;
  margin-bottom: 8px;
  font-size: 18px;
  color: #ffba00;
}

.alert-content {
  margin: 0;
}

.steps {
	padding-inline-start: 15px;
}



@media (min-width: 576px) {
    .nav:not(.nav-hidden).nav-stacked>.bslib-nav-spacer {
        margin-top: 20px !important;
    }
}

@media (min-width: 768px) {
	.main {
		max-width: none;
		padding-right: 0px;
	}
	.col-sm-8 {
		max-width: 62%;
	}
}
